<?php

namespace Tests\Feature\Console;

use Illuminate\Support\Facades\File;
use Tests\TestCase;

class MakeModuleTest extends TestCase
{
    /**
     * Module generated by the tests (removed afterwards).
     */
    protected const MODULE = 'ZzGeneratedSample';

    protected function tearDown(): void
    {
        File::deleteDirectory(base_path('modules/'.self::MODULE));

        parent::tearDown();
    }

    public function test_module_skeleton_is_generated_following_the_merdeka_structure(): void
    {
        $this->artisan('make:module', ['name' => self::MODULE])->assertSuccessful();

        $module = base_path('modules/'.self::MODULE);

        foreach ([
            'Providers/ZzGeneratedSampleServiceProvider.php',
            'Http/Controllers/ZzGeneratedSampleController.php',
            'Http/Requests/ZzGeneratedSampleRequest.php',
            'Http/Middleware/ZzGeneratedSampleMiddleware.php',
            'Models/ZzGeneratedSample.php',
            'Repositories/ZzGeneratedSampleInterface.php',
            'Repositories/ZzGeneratedSampleRepository.php',
            'Routes/web/zz-generated-sample.php',
            'Resources/views/index.blade.php',
        ] as $file) {
            $this->assertFileExists($module.'/'.$file);
        }

        $routes = File::get($module.'/Routes/web/zz-generated-sample.php');
        $this->assertStringContainsString("Route::middleware(['web', 'auth', 'permission'])", $routes);
        $this->assertStringContainsString("->name('zz-generated-sample.')", $routes);
        $this->assertStringContainsString(
            'namespace Modules\ZzGeneratedSample\Http\Controllers;',
            File::get($module.'/Http/Controllers/ZzGeneratedSampleController.php')
        );
        $this->assertStringNotContainsString('{{', File::get($module.'/Repositories/ZzGeneratedSampleRepository.php'));
    }

    public function test_existing_module_is_not_overwritten_without_force(): void
    {
        $this->artisan('make:module', ['name' => self::MODULE])->assertSuccessful();

        $this->artisan('make:module', ['name' => self::MODULE])->assertFailed();
    }

    public function test_invalid_module_names_are_rejected(): void
    {
        $this->artisan('make:module', ['name' => '../Escape'])->assertFailed();

        $this->assertDirectoryDoesNotExist(base_path('modules/Escape'));
    }

    public function test_component_is_added_to_an_existing_module(): void
    {
        $this->artisan('make:module', ['name' => self::MODULE])->assertSuccessful();

        $this->artisan('make:module-component', [
            'module' => self::MODULE,
            'type' => 'repository',
            'name' => 'Certificate',
        ])->assertSuccessful();

        $this->assertFileExists(base_path('modules/'.self::MODULE.'/Repositories/CertificateInterface.php'));
        $this->assertFileExists(base_path('modules/'.self::MODULE.'/Repositories/CertificateRepository.php'));
    }

    public function test_component_requires_an_existing_module(): void
    {
        $this->artisan('make:module-component', [
            'module' => 'DoesNotExist',
            'type' => 'controller',
            'name' => 'Report',
        ])->assertFailed();
    }
}
